const IMC_BACKUP_DB='tanshu-instant-multi-customer-backup-v1';
const openImcBackupDb=()=>new Promise<IDBDatabase>((resolve,reject)=>{const request=indexedDB.open(IMC_BACKUP_DB,1);request.onupgradeneeded=()=>request.result.createObjectStore('sessions');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});
const writeImcBackup=async(value:unknown)=>{const db=await openImcBackupDb();await new Promise<void>((resolve,reject)=>{const tx=db.transaction('sessions','readwrite');tx.objectStore('sessions').put(value,'current');tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});db.close();};
const readImcBackup=async()=>{const db=await openImcBackupDb();const value=await new Promise<any>((resolve,reject)=>{const request=db.transaction('sessions','readonly').objectStore('sessions').get('current');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});db.close();return value;};
