const makeAdjusted = async (customer: CustomerPhoto) => {
  const img = await loadImage(customer.workingUrl);
  const canvas = document.createElement('canvas'); canvas.width = img.naturalWidth; canvas.height = img.naturalHeight;
  const ctx = canvas.getContext('2d'); if (!ctx) return customer.workingUrl;
  const detail = Math.max(0, customer.sharpness + customer.clarity * 0.45 + customer.qualityEnhance * 0.35 + customer.hdEnhance * 0.55);
  const beautySoft = Math.min(0.28, (customer.beauty + customer.smooth + customer.blemish + customer.plump * 0.25 + customer.evenSkin * 0.2) / 900);
  const lightLift = customer.brilliance * 0.12 + customer.shadows * 0.08 + customer.whites * 0.06 + customer.hslLightness * 0.08 + customer.brightEyes * 0.025 + customer.darkCircle * 0.025 + customer.whitening * 0.025 + customer.clear * 0.04;
  const toneContrast = customer.graphic * 0.12 + customer.highlights * 0.05 - customer.blacks * 0.04;
  ctx.filter = [
    'brightness(' + Math.max(45, Math.min(165, customer.brightness + customer.faceTone * 0.12 + customer.skinTone * 0.08 + customer.evenSkin * 0.025 + lightLift)) + '%)',
    'contrast(' + Math.max(55, Math.min(175, customer.contrast + customer.clarity * 0.18 + detail * 0.08 + toneContrast)) + '%)',
    'saturate(' + Math.max(0, Math.min(240, customer.saturation + customer.selectiveColor * 0.25 + customer.hslSaturation * 0.55 + customer.graphic * 0.12)) + '%)',
    'sepia(' + Math.max(0, Math.min(0.3, (customer.colorGrade + customer.temperature * 0.7) / 650)) + ')',
    'hue-rotate(' + (customer.hue + customer.hslHue + customer.hairTone * -0.08) + 'deg)',
    'blur(' + beautySoft + 'px)',
  ].join(' ');
  ctx.drawImage(img, 0, 0); ctx.filter = 'none';
  if (detail > 0) { ctx.globalAlpha = Math.min(0.22, detail / 450); ctx.globalCompositeOperation = 'soft-light'; ctx.drawImage(canvas, 0, 0); ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over'; }
  return canvasUrl(canvas);
};
const removePhotoBackground = async (src: string, onProgress: (fraction: number, message?: string) => void) => {
  const response = await fetch(src);
  if (!response.ok) throw new Error('Could not read the selected customer photo.');
  const sourceBlob = await response.blob();
  const result = await removeBackground(sourceBlob, {
    quality: 'quality',
    onProgress: ({ progress, message }) => { const value = Number(progress) || 0; onProgress(Math.max(0, Math.min(1, value > 1 ? value / 100 : value)), message); },
  });
  return URL.createObjectURL(result.blob);
};

// Signature images are usually dark ink on white paper. Use a lightweight
// local pixel matte instead of loading the heavy AI segmentation model.
const removeSignaturePaperFast = async (src: string) => {
  const img = await loadImage(src);
  const maxSide = 1800;
  const ratio = Math.min(1, maxSide / Math.max(img.naturalWidth, img.naturalHeight));
  const canvas = document.createElement('canvas');
  canvas.width = Math.max(1, Math.round(img.naturalWidth * ratio));
  canvas.height = Math.max(1, Math.round(img.naturalHeight * ratio));
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  if (!ctx) throw new Error('Could not prepare signature image.');
  ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
  const frame = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const pixels = frame.data;
  const paperThreshold = 38;
  for (let i = 0; i < pixels.length; i += 4) {
    const r = pixels[i], g = pixels[i + 1], b = pixels[i + 2];
    const darkness = 255 - Math.min(r, g, b);
    const alpha = Math.max(0, Math.min(1, (darkness - paperThreshold) / (255 - paperThreshold)));
    if (alpha <= 0.015) {
      pixels[i + 3] = 0;
      continue;
    }
    const paper = 255 * (1 - alpha);
    pixels[i] = Math.max(0, Math.min(255, Math.round((r - paper) / alpha)));
    pixels[i + 1] = Math.max(0, Math.min(255, Math.round((g - paper) / alpha)));
    pixels[i + 2] = Math.max(0, Math.min(255, Math.round((b - paper) / alpha)));
    pixels[i + 3] = Math.round(alpha * 255);
  }
  ctx.putImageData(frame, 0, 0);
  const blob = await new Promise<Blob>((resolve, reject) => canvas.toBlob(value => value ? resolve(value) : reject(new Error('Could not save transparent signature.')), 'image/png'));
  return URL.createObjectURL(blob);
};

